#include "sc_hal.h"
#include "sc_seq.h"
#include "sc_pd.h"
#include "sc_rtc.h"
#include "sc_wdt.h"

/* A reference bring-up flow that ties the scaffold together.  A real  */
/* app supplies its own main() / Zephyr thread and the sc_hal port;    */
/* this shows the C2-correct ORDER: rails -> modules -> THEN arm WDT.  */
int sc_bringup_main(void) {
    sc_log("SC bring-up: sequencing rails (DIP-gated, SC veto only)");
    /* PD negotiation is optional here: the board runs reduced on the  */
    /* 5 V default contract until a PD stack lifts +VIN.               */
    (void)sc_pd_init();

    /* C2: the watchdog is NOT armed yet -- sequence first. */
    if (sc_seq_run(/*policy=*/NULL) != 0) {
        sc_log("bring-up FAULT -- leaving watchdog disarmed");
        return -1;
    }

    /* Bring-up complete: NOW it is safe to arm the watchdog (C2). */
    sc_wdt_arm();

    /* RTC: enable the RV-3028 trickle charger so the rechargeable ML1220 */
    /* backup cell tops up.  Best-effort -- the RTC is on the gated AUX   */
    /* rail, so this only takes once that rail + its I2C isolator are up. */
    (void)sc_rtc_init();

    sc_log("SC bring-up complete; watchdog armed");
    return 0;
}
